/**
 * Demo-data seeder — creates a realistic school roster plus `historyDays` of
 * backfilled punches generated by the same engine the mock hardware uses, so
 * the whole dashboard is alive from the very first request. No-op when the
 * database already contains data (or SEED_DEMO=false).
 *
 * CLI:  node src/db/seed.js            seed if empty
 *       node src/db/seed.js --force    wipe ALL data and reseed
 */
const config = require('../config');
const { getDb } = require('./connection');
const { migrate } = require('./migrate');
const { generateDayPunches } = require('../zk/mockDevice');
const { recomputeDate } = require('../services/processor');

const SHIFTS = [
  { name: 'Morning Shift', start_time: '08:00', end_time: '15:30', grace_period_minutes: 10, is_default: 1, description: 'Standard teaching shift' },
  { name: 'Primary Wing', start_time: '07:45', end_time: '14:15', grace_period_minutes: 10, is_default: 0, description: 'Early shift for primary section' },
  { name: 'Admin Hours', start_time: '09:00', end_time: '17:00', grace_period_minutes: 15, is_default: 0, description: 'Office & administration staff' },
];

const TEACHERS = [
  ['101', 'Ayesha Khan', 'Science', 'Teacher', 1],
  ['102', 'Bilal Ahmed', 'Mathematics', 'Teacher', 1],
  ['103', 'Clara D’Souza', 'English', 'Teacher', 2],
  ['104', 'Danish Raza', 'Science', 'Teacher', 1],
  ['105', 'Fatima Noor', 'Mathematics', 'Teacher', 1],
  ['106', 'George Mathew', 'Computer Science', 'Teacher', 1],
  ['107', 'Hina Malik', 'Social Studies', 'Teacher', 2],
  ['108', 'Imran Siddiqui', 'Physical Education', 'Staff', 1],
  ['109', 'Javeria Aslam', 'English', 'Teacher', 1],
  ['110', 'Kamran Ali', 'Urdu', 'Teacher', 2],
  ['111', 'Laila Rahman', 'Admin', 'Staff', 3],
  ['112', 'Mohsin Tariq', 'Admin', 'Staff', 3],
  ['113', 'Nadia Hussain', 'Science', 'Teacher', 1],
  ['114', 'Omar Farooq', 'Mathematics', 'Teacher', 1],
  ['115', 'Priya Sharma', 'Computer Science', 'Teacher', 1],
];

function dateStrOffset(daysAgo) {
  const d = new Date(Date.now() - daysAgo * 864e5);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function wipe() {
  const db = getDb();
  db.exec('BEGIN');
  for (const t of ['processed_attendance', 'attendance_logs', 'teachers', 'shifts', 'sync_state', 'calendar_holidays']) {
    db.exec(`DELETE FROM ${t}`);
  }
  db.prepare("UPDATE calendar_settings SET working_days = '[1,2,3,4,5]' WHERE id = 1").run();
  db.exec('COMMIT');
  console.log('[seed] wiped existing data');
}

function seed({ force = false } = {}) {
  const db = getDb();
  const hasTeachers = db.prepare('SELECT COUNT(*) c FROM teachers').get().c > 0;
  if (hasTeachers && !force) return false;
  if (force) wipe();

  const insertShift = db.prepare(
    `INSERT INTO shifts (name, start_time, end_time, grace_period_minutes, description, is_default)
     VALUES (@name, @start_time, @end_time, @grace_period_minutes, @description, @is_default)`
  );
  const insertTeacher = db.prepare(
    `INSERT INTO teachers (zk_user_id, full_name, department, designation, shift_id, email, phone, status)
     VALUES (?, ?, ?, ?, ?, ?, ?, 'active')`
  );
  const insertLog = db.prepare(
    `INSERT OR IGNORE INTO attendance_logs (teacher_id, zk_user_id, device_sn, punch_time, punch_type, source)
     VALUES (?, ?, 'SIMZKTECO0001', ?, ?, 'seed')`
  );

  db.exec('BEGIN');
  try {
    for (const s of SHIFTS) insertShift.run(s);
    for (const [zkId, name, dept, desig, shiftId] of TEACHERS) {
      const local = name.split(' ')[0].toLowerCase().replace(/[^a-z]/g, '');
      insertTeacher.run(
        zkId, name, dept, desig, shiftId,
        `${local}${zkId}@school.edu`,
        `+92-300-${String(1000000 + Number(zkId)).slice(0, 7)}`
      );
    }

    // Backfill history (skip today — the live poller/web simulator owns today).
    const teacherRows = db
      .prepare(
        `SELECT t.id, t.zk_user_id, COALESCE(s.start_time, d.start_time) AS st,
                COALESCE(s.end_time, d.end_time) AS et
         FROM teachers t
         LEFT JOIN shifts s ON s.id = t.shift_id
         LEFT JOIN shifts d ON d.is_default = 1
         WHERE t.status = 'active'`
      )
      .all();

    for (let ago = config.seed.historyDays; ago >= 1; ago--) {
      const dateStr = dateStrOffset(ago);
      for (const t of teacherRows) {
        for (const p of generateDayPunches({
          userId: t.zk_user_id,
          dateStr,
          shiftStart: t.st,
          shiftEnd: t.et,
        })) {
          insertLog.run(t.id, t.zk_user_id, p.timestamp, p.punchType);
        }
      }
    }
    db.exec('COMMIT');

    for (let ago = config.seed.historyDays; ago >= 1; ago--) {
      recomputeDate(dateStrOffset(ago));
    }
    console.log(`[seed] demo data ready: ${TEACHERS.length} teachers, ${config.seed.historyDays} days of punches processed`);
    return true;
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

function seedIfEmpty() {
  if (!config.seed.demoData) return false;
  try {
    return seed();
  } catch (err) {
    console.error('[seed] failed:', err.message);
    return false;
  }
}

if (require.main === module) {
  migrate();
  const force = process.argv.includes('--force');
  const done = seed({ force });
  console.log(done ? '[seed] done' : '[seed] skipped (database not empty — use --force to reseed)');
}

module.exports = { seed, seedIfEmpty };
